questions.solution:
class Account {
  constructor(balance) { this.balance = balance; }
  withdraw(sum) {
    if (sum > this.balance) throw new Error("Недостаточно средств");
    this.balance -= sum;
  }
}
let acc = new Account(100);
let sum = Number(prompt());
try {
  acc.withdraw(sum);
  console.log(acc.balance);
} catch (e) {
  console.log(e.message);
}

