const secret = 42;
let tries = 0;
while (true) {
  let g = Number(prompt());
  tries++;
  if (g > secret) console.log("меньше");
  else if (g < secret) console.log("больше");
  else { console.log(`угадал за ${tries} попыток`); break; }
}

